from taf.ul.ettf.logger import custom_logger


logger = custom_logger('ObjectProvider')


def log_created(object_type, obj):
    log('Object created. Type: {}, id: {}', object_type, obj)


def log_already_created(object_type, obj):
    log('Object already created. Type: {}, id: {}', object_type, obj)


def log(message, object_type, obj):
    logger.debug(message.format(object_type, id(obj.instance)))
